def normalize(nodes, edges):
    """Return sorted node list, adjacency dict, and indegree dict.

    Deduplicate nodes and edges, reject unknown nodes, self‑loops and
    duplicate edges.  Indegrees count incoming edges.
    """
    # Deduplicate nodes and sort
    names = sorted(set(nodes))
    adjacency = {n: [] for n in names}
    indegree = {n: 0 for n in names}

    # Deduplicate edges
    unique_edges = set(tuple(e) for e in edges)
    for left, right in unique_edges:
        if left not in adjacency or right not in adjacency:
            raise ValueError("unknown node")
        if left == right:
            raise ValueError("self‑loop")
        adjacency[left].append(right)
        indegree[right] += 1
    return names, adjacency, indegree

